class Solution:
    def minOperationsToEqualize(self, grid, k):
        m, n = len(grid), len(grid[0])
        base = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                d = -grid[i][j]
                if i > 0: d += grid[i - 1][j]
                if j > 0: d += grid[i][j - 1]
                if i > 0 and j > 0: d -= grid[i - 1][j - 1]
                a = base[i][j - k] if j >= k else 0
                b = base[i - k][j] if i >= k else 0
                c = base[i - k][j - k] if (i >= k and j >= k) else 0
                base[i][j] = d + a + b - c
        lo = max(max(r) for r in grid)
        eq = None
        for i in range(m):
            for j in range(n):
                lat = (i % k == 0 and j % k == 0)
                valid = i <= m - k and j <= n - k
                if lat:
                    if valid:
                        lo = max(lo, -base[i][j])
                    else:
                        v = -base[i][j]
                        if eq is None: eq = v
                        elif eq != v: return -1
                else:
                    if valid:
                        if base[i][j] < 0: return -1
                    elif base[i][j] != 0:
                        return -1
        T = eq if eq is not None else lo
        ans = 0
        for i in range(0, m, k):
            for j in range(0, n, k):
                if i <= m - k and j <= n - k:
                    ans += base[i][j] + T
        return ans

